sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
console.log('hello');
    var a =api.data.decision_side_panel.form.fields;
    var newkeys={};
    for (var key in a) {
    if (a.hasOwnProperty(key)) { // Ensures you only get the object's own properties
        //console.log(a[key]);
        if(key=='reason'|| key=='comments'){
            newkeys[key]=a[key]
        }
    }
}
api.data.record.form.fields=newkeys;
console.log(newkeys);
return newkeys;
}
